1	import type { RGB, HSL, OKLCH, Color, ContrastInfo, CssColorFormat, Gamut } from './types.js';
2	import { rgbToOklch, p3ToSrgb, srgbToP3, relativeLuminance } from './color-space.js';
3	
4	// ---------------------------------------------------------------------------
5	// Internal helpers
6	// ---------------------------------------------------------------------------
7	
8	function rgbToHsl(r: number, g: number, b: number): HSL {
9	    const r1 = r / 255;
10	    const g1 = g / 255;
11	    const b1 = b / 255;
12	    const max = Math.max(r1, g1, b1);
13	    const min = Math.min(r1, g1, b1);
14	    const l = (max + min) / 2;
15	    let h = 0;
16	    let s = 0;
17	
18	    if (max !== min) {
19	        const d = max - min;
20	        s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
21	
22	        if (max === r1) {
23	            h = ((g1 - b1) / d + (g1 < b1 ? 6 : 0)) / 6;
24	        } else if (max === g1) {
25	            h = ((b1 - r1) / d + 2) / 6;
26	        } else {
27	            h = ((r1 - g1) / d + 4) / 6;
28	        }
29	    }
30	
31	    return {
32	        h: Math.round(h * 360),
33	        s: Math.round(s * 100),
34	        l: Math.round(l * 100),
35	    };
36	}
37	
38	/** WCAG contrast ratio between two luminances (always ≥ 1). */
39	function contrastRatio(l1: number, l2: number): number {
40	    const lighter = Math.max(l1, l2);
41	    const darker = Math.min(l1, l2);
42	    return (lighter + 0.05) / (darker + 0.05);
43	}
