46	// ColorImpl
47	// ---------------------------------------------------------------------------
48	
49	class ColorImpl implements Color {
50	    // Channels are stored in the color's native gamut (_gamut).
51	    private readonly _r: number;
52	    private readonly _g: number;
53	    private readonly _b: number;
54	    readonly gamut: Gamut;
55	    readonly population: number;
56	    readonly proportion: number;
57	
58	    private _srgb: [number, number, number] | undefined;
59	    private _hsl: HSL | undefined;
60	    private _oklch: OKLCH | undefined;
61	    private _luminance: number | undefined;
62	    private _contrast: ContrastInfo | undefined;
63	
64	    constructor(
65	        r: number,
66	        g: number,
67	        b: number,
68	        population: number,
69	        proportion: number,
70	        gamut: Gamut = 'srgb',
71	    ) {
72	        this._r = r;
73	        this._g = g;
74	        this._b = b;
75	        this.gamut = gamut;
76	        this.population = population;
77	        this.proportion = proportion;
78	    }
79	
80	    /** Channels gamut-mapped to sRGB (identity when already sRGB). */
81	    private get srgb(): [number, number, number] {
82	        if (!this._srgb) {
83	            this._srgb =
84	                this.gamut === 'display-p3'
85	                    ? p3ToSrgb(this._r, this._g, this._b)
86	                    : [this._r, this._g, this._b];
87	        }
88	        return this._srgb;
89	    }
90	
91	    rgb(gamut: Gamut = 'srgb'): RGB {
92	        if (gamut === this.gamut) {
93	            return { r: this._r, g: this._g, b: this._b };
94	        }
95	        // gamut differs from native: convert.
96	        const [r, g, b] =
97	            gamut === 'display-p3'
98	                ? srgbToP3(this._r, this._g, this._b) // native is sRGB
99	                : this.srgb; // native is P3
100	        return { r, g, b };
101	    }
102	
103	    hex(): string {
104	        const [r, g, b] = this.srgb;
105	        const toHex = (n: number) => n.toString(16).padStart(2, '0');
106	        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
107	    }
108	
109	    hsl(): HSL {
110	        if (!this._hsl) {
111	            const [r, g, b] = this.srgb;
112	            this._hsl = rgbToHsl(r, g, b);
113	        }
114	        return this._hsl;
115	    }
116	
117	    oklch(): OKLCH {
118	        if (!this._oklch) {
119	            this._oklch = rgbToOklch(this._r, this._g, this._b, this.gamut);
120	        }
121	        return this._oklch;
122	    }
123	
124	    css(format?: CssColorFormat): string {
125	        // Default format preserves the color's native gamut.
126	        if (format === undefined) {
127	            if (this.gamut === 'display-p3') {
128	                const f = (n: number) => +(n / 255).toFixed(4);
129	                return `color(display-p3 ${f(this._r)} ${f(this._g)} ${f(this._b)})`;
130	            }
131	            format = 'rgb';
132	        }
133	        switch (format) {
134	            case 'hsl': {
135	                const { h, s, l } = this.hsl();
136	                return `hsl(${h}, ${s}%, ${l}%)`;
137	            }
138	            case 'oklch': {
139	                const { l, c, h } = this.oklch();
140	                return `oklch(${l.toFixed(3)} ${c.toFixed(3)} ${h.toFixed(1)})`;
141	            }
142	            case 'rgb':
143	            default: {
144	                const [r, g, b] = this.srgb;
145	                return `rgb(${r}, ${g}, ${b})`;
146	            }
147	        }
148	    }
149	
150	    array(): [number, number, number] {
151	        return [...this.srgb];
152	    }
153	
154	    toString(): string {
155	        return this.hex();
156	    }
157	
158	    get textColor(): string {
159	        return this.isDark ? '#ffffff' : '#000000';
160	    }
161	
162	    private get luminance(): number {
163	        if (this._luminance === undefined) {
164	            this._luminance = relativeLuminance(this._r, this._g, this._b, this.gamut);
165	        }
166	        return this._luminance;
167	    }
168	
169	    get isDark(): boolean {
170	        return this.luminance <= 0.179;
171	    }
172	
173	    get isLight(): boolean {
174	        return !this.isDark;
175	    }
176	
177	    get contrast(): ContrastInfo {
178	        if (!this._contrast) {
179	            const lum = this.luminance;
180	            const white = contrastRatio(lum, 1); // white luminance = 1
181	            const black = contrastRatio(lum, 0); // black luminance = 0
182	            const foreground = this.isDark
183	                ? createColor(255, 255, 255, 0, 0)
184	                : createColor(0, 0, 0, 0, 0);
185	            this._contrast = {
186	                white: Math.round(white * 100) / 100,
187	                black: Math.round(black * 100) / 100,
188	                foreground,
189	            };
190	        }
191	        return this._contrast;
192	    }
193	}
194	
195	// ---------------------------------------------------------------------------
196	// Factory
197	// ---------------------------------------------------------------------------
198	
199	/**
200	 * Create a Color object from RGB components, population count, and proportion.
201	 * Components are interpreted in `gamut` (default `'srgb'`).
202	 */
203	export function createColor(
204	    r: number,
205	    g: number,
206	    b: number,
207	    population: number,
208	    proportion: number = 0,
209	    gamut: Gamut = 'srgb',
210	): Color {
211	    return new ColorImpl(r, g, b, population, proportion, gamut);
212	}
