1: import type { BrowserSource, Gamut, PixelData, PixelLoader } from '../types.js';
2: import { readViaCanvas, readFromContext } from './canvas-utils.js';
3: 
4: /**
5:  * Browser pixel loader. Extracts RGBA pixel data from DOM image sources
6:  * using an off-screen canvas.
7:  *
8:  * The optional `gamut` argument controls the color space pixels are read in:
9:  * `'srgb'` (default), `'display-p3'`, or `'auto'`. It falls back to sRGB when
10:  * the environment lacks P3 canvas support.
11:  */
12: export class BrowserPixelLoader implements PixelLoader<BrowserSource> {
13:     async load(source: BrowserSource, _signal?: AbortSignal, gamut: Gamut | 'auto' = 'srgb'): Promise<PixelData> {
14:         if (typeof HTMLImageElement !== 'undefined' && source instanceof HTMLImageElement) {
15:             return this.loadFromImage(source, gamut);
16:         }
17:         if (typeof HTMLCanvasElement !== 'undefined' && source instanceof HTMLCanvasElement) {
18:             return this.loadFromCanvas(source, gamut);
19:         }
20:         if (typeof ImageData !== 'undefined' && source instanceof ImageData) {
21:             return {
22:                 data: source.data,
23:                 width: source.width,
24:                 height: source.height,
25:                 // ImageData carries its own color space — honor it.
26:                 colorSpace: (source.colorSpace as Gamut) ?? 'srgb',
27:             };
28:         }
29:         if (typeof HTMLVideoElement !== 'undefined' && source instanceof HTMLVideoElement) {
30:             return this.loadFromVideo(source, gamut);
31:         }
32:         if (typeof ImageBitmap !== 'undefined' && source instanceof ImageBitmap) {
33:             return this.loadFromImageBitmap(source, gamut);
34:         }
35:         if (typeof OffscreenCanvas !== 'undefined' && source instanceof OffscreenCanvas) {
36:             return this.loadFromOffscreenCanvas(source, gamut);
37:         }
38:         throw new Error(
39:             'Unsupported source type. Expected HTMLImageElement, HTMLCanvasElement, HTMLVideoElement, ImageData, ImageBitmap, or OffscreenCanvas.',
40:         );
41:     }
42: 
43:     private loadFromImage(img: HTMLImageElement, gamut: Gamut | 'auto'): PixelData {
44:         if (!img.complete) {
45:             throw new Error(
46:                 'Image has not finished loading. Wait for the "load" event before calling getColor/getPalette.',
47:             );
48:         }
49:         if (!img.naturalWidth) {
50:             throw new Error(
51:                 'Image has no dimensions. It may not have loaded successfully.',
52:             );
53:         }
54:         return readViaCanvas(img.naturalWidth, img.naturalHeight, gamut, (ctx) =>
55:             ctx.drawImage(img, 0, 0, img.naturalWidth, img.naturalHeight),
56:         );
57:     }
58: 
59:     private loadFromCanvas(canvas: HTMLCanvasElement, gamut: Gamut | 'auto'): PixelData {
60:         const ctx = canvas.getContext('2d')!;
61:         return readFromContext(ctx, canvas.width, canvas.height, gamut);
62:     }
63: 
64:     private loadFromVideo(video: HTMLVideoElement, gamut: Gamut | 'auto'): PixelData {
65:         if (video.readyState < 2) {
66:             throw new Error(
67:                 'Video is not ready. Wait for the "loadeddata" or "canplay" event before calling getColor/getPalette.',
68:             );
69:         }
70:         const width = video.videoWidth;
71:         const height = video.videoHeight;
72:         if (!width || !height) {
73:             throw new Error(
74:                 'Video has no dimensions. It may not have loaded successfully.',
75:             );
76:         }
77:         return readViaCanvas(width, height, gamut, (ctx) =>
78:             ctx.drawImage(video, 0, 0, width, height),
79:         );
80:     }
81: 
82:     private loadFromOffscreenCanvas(canvas: OffscreenCanvas, gamut: Gamut | 'auto'): PixelData {
83:         const ctx = canvas.getContext('2d') as OffscreenCanvasRenderingContext2D;
84:         if (!ctx) {
85:             throw new Error(
86:                 'Could not get 2D context from OffscreenCanvas.',
