25: class VBox {
26:     r1: number;
27:     r2: number;
28:     g1: number;
29:     g2: number;
30:     b1: number;
31:     b2: number;
32: 
33:     private readonly histo: Uint32Array;
34:     private _volume: number | undefined;
35:     private _count: number | undefined;
36:     private _avg: [number, number, number] | undefined;
37: 
38:     constructor(
39:         r1: number,
40:         r2: number,
41:         g1: number,
42:         g2: number,
43:         b1: number,
44:         b2: number,
45:         histo: Uint32Array,
46:     ) {
47:         this.r1 = r1;
48:         this.r2 = r2;
49:         this.g1 = g1;
50:         this.g2 = g2;
51:         this.b1 = b1;
52:         this.b2 = b2;
53:         this.histo = histo;
54:     }
55: 
56:     volume(force = false): number {
57:         if (this._volume === undefined || force) {
58:             this._volume =
59:                 (this.r2 - this.r1 + 1) *
60:                 (this.g2 - this.g1 + 1) *
61:                 (this.b2 - this.b1 + 1);
62:         }
63:         return this._volume;
64:     }
65: 
66:     count(force = false): number {
67:         if (this._count === undefined || force) {
68:             let npix = 0;
69:             for (let i = this.r1; i <= this.r2; i++) {
70:                 for (let j = this.g1; j <= this.g2; j++) {
71:                     for (let k = this.b1; k <= this.b2; k++) {
72:                         npix += this.histo[getColorIndex(i, j, k)] || 0;
73:                     }
74:                 }
75:             }
76:             this._count = npix;
77:         }
78:         return this._count;
79:     }
80: 
81:     copy(): VBox {
82:         return new VBox(this.r1, this.r2, this.g1, this.g2, this.b1, this.b2, this.histo);
83:     }
84: 
85:     avg(force = false): [number, number, number] {
86:         if (this._avg === undefined || force) {
87:             const mult = 1 << RSHIFT;
88: 
89:             // Single-color box: return exact color
90:             if (this.r1 === this.r2 && this.g1 === this.g2 && this.b1 === this.b2) {
91:                 this._avg = [
92:                     this.r1 << RSHIFT,
93:                     this.g1 << RSHIFT,
94:                     this.b1 << RSHIFT,
95:                 ];
96:             } else {
97:                 let ntot = 0;
98:                 let rsum = 0;
99:                 let gsum = 0;
100:                 let bsum = 0;
101: 
102:                 for (let i = this.r1; i <= this.r2; i++) {
103:                     for (let j = this.g1; j <= this.g2; j++) {
104:                         for (let k = this.b1; k <= this.b2; k++) {
105:                             const hval = this.histo[getColorIndex(i, j, k)] || 0;
106:                             ntot += hval;
107:                             rsum += hval * (i + 0.5) * mult;
108:                             gsum += hval * (j + 0.5) * mult;
109:                             bsum += hval * (k + 0.5) * mult;
