176: function getHisto(pixels: Array<[number, number, number]>): Uint32Array {
177:     const histo = new Uint32Array(HISTO_SIZE);
178:     for (const pixel of pixels) {
179:         const rval = pixel[0] >> RSHIFT;
180:         const gval = pixel[1] >> RSHIFT;
181:         const bval = pixel[2] >> RSHIFT;
182:         histo[getColorIndex(rval, gval, bval)]++;
183:     }
184:     return histo;
185: }
