187: function vboxFromPixels(
188:     pixels: Array<[number, number, number]>,
189:     histo: Uint32Array,
190: ): VBox {
191:     let rmin = 1000000;
192:     let rmax = 0;
193:     let gmin = 1000000;
194:     let gmax = 0;
195:     let bmin = 1000000;
196:     let bmax = 0;
197: 
198:     for (const pixel of pixels) {
199:         const rval = pixel[0] >> RSHIFT;
200:         const gval = pixel[1] >> RSHIFT;
201:         const bval = pixel[2] >> RSHIFT;
202:         if (rval < rmin) rmin = rval;
203:         else if (rval > rmax) rmax = rval;
204:         if (gval < gmin) gmin = gval;
205:         else if (gval > gmax) gmax = gval;
206:         if (bval < bmin) bmin = bval;
207:         else if (bval > bmax) bmax = bval;
208:     }
209: 
210:     return new VBox(rmin, rmax, gmin, gmax, bmin, bmax, histo);
211: }
