213: // ---------------------------------------------------------------------------
214: // Median-cut split
215: // ---------------------------------------------------------------------------
216: 
217: function medianCutApply(histo: Uint32Array, vbox: VBox): [VBox, VBox | null] | undefined {
218:     if (!vbox.count()) return undefined;
219: 
220:     // Only one pixel — no split possible
221:     if (vbox.count() === 1) return [vbox.copy(), null];
222: 
223:     const rw = vbox.r2 - vbox.r1 + 1;
224:     const gw = vbox.g2 - vbox.g1 + 1;
225:     const bw = vbox.b2 - vbox.b1 + 1;
226:     const maxw = Math.max(rw, gw, bw);
227: 
228:     let total = 0;
229:     const partialsum: number[] = [];
230:     const lookaheadsum: number[] = [];
231: 
232:     if (maxw === rw) {
233:         for (let i = vbox.r1; i <= vbox.r2; i++) {
234:             let sum = 0;
235:             for (let j = vbox.g1; j <= vbox.g2; j++) {
236:                 for (let k = vbox.b1; k <= vbox.b2; k++) {
237:                     sum += histo[getColorIndex(i, j, k)] || 0;
238:                 }
239:             }
240:             total += sum;
241:             partialsum[i] = total;
242:         }
243:     } else if (maxw === gw) {
244:         for (let i = vbox.g1; i <= vbox.g2; i++) {
245:             let sum = 0;
246:             for (let j = vbox.r1; j <= vbox.r2; j++) {
247:                 for (let k = vbox.b1; k <= vbox.b2; k++) {
248:                     sum += histo[getColorIndex(j, i, k)] || 0;
249:                 }
250:             }
251:             total += sum;
252:             partialsum[i] = total;
253:         }
254:     } else {
255:         for (let i = vbox.b1; i <= vbox.b2; i++) {
256:             let sum = 0;
257:             for (let j = vbox.r1; j <= vbox.r2; j++) {
258:                 for (let k = vbox.g1; k <= vbox.g2; k++) {
259:                     sum += histo[getColorIndex(j, k, i)] || 0;
260:                 }
261:             }
262:             total += sum;
263:             partialsum[i] = total;
264:         }
265:     }
266: 
267:     partialsum.forEach((d, i) => {
268:         lookaheadsum[i] = total - d;
269:     });
270: 
271:     function doCut(color: 'r' | 'g' | 'b'): [VBox, VBox] | undefined {
272:         const dim1 = (color + '1') as 'r1' | 'g1' | 'b1';
273:         const dim2 = (color + '2') as 'r2' | 'g2' | 'b2';
274: 
275:         for (let i = vbox[dim1]; i <= vbox[dim2]; i++) {
276:             if (partialsum[i] > total / 2) {
277:                 const vbox1 = vbox.copy();
278:                 const vbox2 = vbox.copy();
279:                 const left = i - vbox[dim1];
280:                 const right = vbox[dim2] - i;
281: 
282:                 let d2: number;
283:                 if (left <= right) {
284:                     d2 = Math.min(vbox[dim2] - 1, ~~(i + right / 2));
285:                 } else {
286:                     d2 = Math.max(vbox[dim1], ~~(i - 1 - left / 2));
287:                 }
288: 
289:                 // Avoid 0-count boxes
290:                 while (!partialsum[d2]) d2++;
291:                 let count2 = lookaheadsum[d2];
292:                 while (!count2 && partialsum[d2 - 1]) count2 = lookaheadsum[--d2];
293: 
294:                 // Set dimensions
295:                 vbox1[dim2] = d2;
296:                 vbox2[dim1] = vbox1[dim2] + 1;
297: 
298:                 return [vbox1, vbox2];
299:             }
300:         }
301:         return undefined;
302:     }
303: 
304:     if (maxw === rw) return doCut('r');
305:     if (maxw === gw) return doCut('g');
306:     return doCut('b');
307: }
