313: function iterate(pq: PQueue<VBox>, target: number, histo: Uint32Array): void {
314:     let ncolors = pq.size();
315:     let niters = 0;
316: 
317:     while (niters < MAX_ITERATIONS) {
318:         if (ncolors >= target) return;
319:         niters++;
320: 
321:         const vbox = pq.pop();
322: 
323:         if (!vbox.count()) {
324:             pq.push(vbox);
325:             continue;
326:         }
327: 
328:         const result = medianCutApply(histo, vbox);
329:         if (!result || !result[0]) return;
330: 
331:         pq.push(result[0]);
332:         if (result[1]) {
333:             pq.push(result[1]);
334:             ncolors++;
335:         }
336:     }
337: }
