343: function quantize(
344:     pixels: Array<[number, number, number]>,
345:     maxColors: number,
346: ): Array<{ color: [number, number, number]; population: number }> {
347:     if (!pixels.length || maxColors < 2 || maxColors > 256) return [];
348: 
349:     const histo = getHisto(pixels);
350: 
351:     // Get the initial vbox from the pixels
352:     const vbox = vboxFromPixels(pixels, histo);
353:     const pq = new PQueue<VBox>((a, b) => a.count() - b.count());
354:     pq.push(vbox);
355: 
356:     // Phase 1: split by population until FRACT_BY_POPULATIONS * maxColors
357:     iterate(pq, FRACT_BY_POPULATIONS * maxColors, histo);
358: 
359:     // Phase 2: re-sort by count * volume, continue splitting
360:     const pq2 = new PQueue<VBox>((a, b) => a.count() * a.volume() - b.count() * b.volume());
361:     while (pq.size()) {
362:         pq2.push(pq.pop());
363:     }
364:     iterate(pq2, maxColors, histo);
365: 
366:     // Extract palette with population counts
367:     const results: Array<{ color: [number, number, number]; population: number }> = [];
368:     while (pq2.size()) {
369:         const box = pq2.pop();
370:         results.push({
371:             color: box.avg(),
372:             population: box.count(),
373:         });
374:     }
375: 
376:     return results;
377: }
