                    for (let k = this.b1; k <= this.b2; k++) {
                        npix += this.histo[getColorIndex(i, j, k)] || 0;
                    }
                }
            }
            this._count = npix;
        }
        return this._count;
    }

    copy(): VBox {
        return new VBox(this.r1, this.r2, this.g1, this.g2, this.b1, this.b2, this.histo);
    }

    avg(force = false): [number, number, number] {
