1: /**
2:  * Self-contained worker script that receives pixel data, runs quantization,
3:  * and returns the serialized palette.
4:  *
5:  * Message protocol:
6:  *   Request:  { id: number, pixels: number[][], maxColors: number }
7:  *   Response: { id: number, palette: Array<{ color: [r,g,b], population: number }> }
8:  *   Error:    { id: number, error: string }
9:  */
10: 
11: // This entire string is turned into a Blob URL by the worker manager.
12: // It must be fully self-contained — no imports, no external dependencies.
13: export const WORKER_SOURCE = /* js */ `
14: 'use strict';
15: 
16: // -------------------------------------------------------------------------
17: // Inlined MMCQ (Modified Median Cut Quantization)
18: // -------------------------------------------------------------------------
19: 
20: var SIGBITS = 5;
